<script setup lang="ts">
import ResizableSidebar from '../components/ResizableSidebar.vue'
import {ref,watch,onBeforeUnmount,computed} from 'vue'
import type {Snapshot} from '../types'
import {request,download} from '../api'
import CustomSelect from '../components/CustomSelect.vue'
import Icon from '../components/Icon.vue'
const props=defineProps<{state:Snapshot;active:boolean}>(),emit=defineEmits<{refresh:[];error:[unknown];notice:[string]}>()
const tab=ref('tests'),logs=ref<any[]>([]),sessions=ref<any[]>([]),selected=ref(''),session=ref<any>(),characterId=ref('default-character'),worker=ref(''),input=ref(''),busy=ref(false),selectedRun=ref(''),logFilter=ref('')
let timer:ReturnType<typeof setInterval>|undefined
const runs=computed(()=>session.value?.runs??[]),run=computed(()=>runs.value.find((r:any)=>r.id===selectedRun.value)??runs.value.at(-1)),filteredLogs=computed(()=>logs.value.filter(l=>!logFilter.value||JSON.stringify(l).toLowerCase().includes(logFilter.value.toLowerCase())))
async function load(){try{if(tab.value==='logs')logs.value=await request('/developer/logs');else{sessions.value=await request('/developer/tests');if(selected.value)session.value=await request(`/developer/tests/${selected.value}`)}}catch(e){emit('error',e)}}
watch(()=>[props.active,tab.value],()=>{clearInterval(timer);if(props.active){void load();timer=setInterval(load,2500)}},{immediate:true});onBeforeUnmount(()=>clearInterval(timer))
async function select(id:string){selected.value=id;session.value=await request(`/developer/tests/${id}`);selectedRun.value=''}
async function create(){try{const s=await request('/developer/tests',{characterId:characterId.value});await select(s.id);await load();emit('notice','隔离测试已创建')}catch(e){emit('error',e)}}
async function execute(){if(!input.value.trim()||!selected.value)return;busy.value=true;try{await request(`/developer/tests/${selected.value}/run`,{input:input.value,...(worker.value?{worker:worker.value}:{})});await load()}catch(e){emit('error',e)}finally{busy.value=false}}
async function cancel(){try{await request(`/developer/tests/${selected.value}/cancel`,{});await load()}catch(e){emit('error',e)}}
async function diagnostics(){try{download('沙之书-诊断.json',await request('/developer/diagnostics'))}catch(e){emit('error',e)}}
function status(value:string){return ({completed:'完成',failed:'失败',cancelled:'已取消',running:'执行中',queued:'排队中'} as Record<string,string>)[value]??value}
</script>
<template><section class="page-view developer-page business-page"><header class="page-header"><div><h1>开发者</h1></div><button class="button" @click="diagnostics"><Icon name="download" :size="16"/>导出诊断</button></header><div class="page-tabs"><button :aria-selected="tab==='tests'" @click="tab='tests'"><Icon name="test" :size="16"/>隔离测试</button><button :aria-selected="tab==='logs'" @click="tab='logs'"><Icon name="list" :size="16"/>运行日志</button></div><div v-if="tab==='tests'" class="test-workspace"><ResizableSidebar name="测试列表" storage-key="tests" :width="260" :min="200" :max="380"><aside class="test-sidebar"><label class="field">测试角色<CustomSelect v-model="characterId" aria-label="测试角色" :options="state.characters.map(p=>({value:p.id,label:p.name}))"/></label><button class="button full-width" @click="create"><Icon name="plus" :size="16"/>新建隔离测试</button><div class="test-session-list"><button v-for="s in sessions" :key="s.id" :class="{selected:s.id===selected}" @click="select(s.id)"><strong>{{s.label??state.characters.find(c=>c.id===s.characterId)?.name??'角色测试'}}</strong><span>{{new Date(s.createdAt).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})}}</span></button></div></aside></ResizableSidebar><div v-if="!selected" class="test-empty empty-section"><Icon name="terminal" :size="34"/><h3>选择或新建测试</h3><p>测试结果仅写入独立副本。</p></div><div v-else class="test-main"><form @submit.prevent="execute" class="test-input"><div class="form-grid two"><label class="field">执行对象<CustomSelect v-model="worker" aria-label="执行对象" :options="[{value:'',label:'主对话 Agent'},...state.prompts.filter(p=>p.scope==='worker').map(p=>({value:p.name,label:p.label??p.name}))]"/></label></div><label class="field">测试输入<textarea v-model="input" rows="3" placeholder="输入测试内容"/></label><div class="form-footer"><button v-if="busy" type="button" class="button" @click="cancel"><Icon name="stop" :size="15"/>停止</button><button class="button primary" :disabled="busy||!input.trim()"><Icon name="play" :size="15"/>{{busy?'执行中…':'运行测试'}}</button></div></form><div v-if="runs.length" class="test-results"><div class="run-selector"><button v-for="r in runs" :key="r.id" :class="{selected:run?.id===r.id}" @click="selectedRun=r.id">{{r.worker??'Agent'}} · {{status(r.status)}}</button></div><div v-if="run" class="run-detail"><div class="section-heading"><h3>执行结果</h3><span :class="run.status==='failed'?'inline-error':'muted'">{{status(run.status)}}</span></div><p v-if="run.error" class="inline-error">{{run.error}}</p><pre class="preview-code">{{JSON.stringify(run.output??{},null,2)}}</pre><details><summary>模型请求与本次上下文<Icon class="disclosure-arrow" name="down" :size="14"/></summary><pre class="preview-code">{{JSON.stringify(run.request??{},null,2)}}</pre></details><details><summary>执行步骤 · {{run.steps?.length??0}}<Icon class="disclosure-arrow" name="down" :size="14"/></summary><pre class="preview-code">{{JSON.stringify(run.steps??[],null,2)}}</pre></details><details><summary>副本写入 · {{run.writes?.length??0}}<Icon class="disclosure-arrow" name="down" :size="14"/></summary><pre class="preview-code">{{JSON.stringify(run.writes??[],null,2)}}</pre></details></div></div><p v-else class="test-awaiting muted">暂无执行结果</p></div></div><div v-else class="logs-workspace"><div class="search-field"><Icon name="search" :size="16"/><input v-model="logFilter" placeholder="筛选事件或内容" aria-label="筛选日志"/></div><div class="log-list"><details v-for="log in filteredLogs" :key="log.sequence" class="log-entry"><summary><time>{{new Date(log.time??log.createdAt??log.timestamp).toLocaleTimeString('zh-CN')}}</time><span class="log-level">{{log.level}}</span><strong>{{log.event}}</strong><Icon class="disclosure-arrow" name="down" :size="14"/></summary><pre class="preview-code">{{JSON.stringify(log.payload,null,2)}}</pre></details><p v-if="!filteredLogs.length" class="muted empty-section">没有匹配的日志。</p></div></div></section></template>
<style src="../business-components.css"></style>
